-- =====================================================================
-- Org Health Clean Room: fake people data for the Beams hackathon
-- Fictional company "Larkspur Labs", ~300 active employees + recent leavers.
-- All names, emails, SSNs and bank details are FAKE.
--
-- Run against the existing hr_demo database:
--   psql -d hr_demo -f database/people_seed.sql
--
-- Adds (does not change Riley's existing tables, views or role):
--   people          raw table, includes sensitive columns
--   v_people_coded  coded view: no names, emails, SSNs or bank details
--   SELECT on v_people_coded granted to the existing readonly_analyst role
-- Reference date for all "last 12 months" measures: 2026-10-01
-- Rating scale: 1 (below) to 4 (exceeds). 4 = top performer.
-- =====================================================================

BEGIN;

DROP VIEW IF EXISTS v_people_coded;
DROP TABLE IF EXISTS people;

CREATE TABLE people (
    emp_id              INTEGER PRIMARY KEY,
    full_name           TEXT NOT NULL,      -- sensitive
    email               TEXT NOT NULL,      -- sensitive
    ssn                 TEXT NOT NULL,      -- sensitive
    bank_account        TEXT NOT NULL,      -- sensitive
    org                 TEXT NOT NULL,
    team                TEXT NOT NULL,
    job_family          TEXT NOT NULL,
    level               TEXT NOT NULL,
    manager_id          INTEGER REFERENCES people(emp_id),
    hire_date           DATE NOT NULL,
    term_date           DATE,
    term_type           TEXT CHECK (term_type IN ('Voluntary','Involuntary')),
    regretted           BOOLEAN,
    rating_current      SMALLINT CHECK (rating_current BETWEEN 1 AND 4),
    rating_prior        SMALLINT CHECK (rating_prior BETWEEN 1 AND 4),
    last_promo_date     DATE,
    manager_changes_12m SMALLINT NOT NULL DEFAULT 0,
    base_salary         NUMERIC(10,2) NOT NULL,
    band_min            NUMERIC(10,2) NOT NULL,
    band_mid            NUMERIC(10,2) NOT NULL,
    band_max            NUMERIC(10,2) NOT NULL
);



-- Coded view: the ONLY thing the agent can read.
-- Names, emails, SSNs and bank details are excluded. People and managers
-- appear as short random-looking codes that can't be traced back to the
-- raw table without access to it.
CREATE VIEW v_people_coded AS
SELECT
    left(md5('lark-' || p.emp_id::text), 10)            AS emp_code,
    p.org,
    p.team,
    p.job_family,
    p.level,
    CASE WHEN p.manager_id IS NULL THEN NULL
         ELSE left(md5('lark-' || p.manager_id::text), 10) END AS manager_code,
    p.hire_date,
    p.term_date,
    p.term_type,
    p.regretted,
    p.rating_current,
    p.rating_prior,
    p.last_promo_date,
    p.manager_changes_12m,
    p.base_salary,
    p.band_min,
    p.band_mid,
    p.band_max
FROM people p;

GRANT SELECT ON v_people_coded TO readonly_analyst;
REVOKE ALL ON people FROM readonly_analyst;

COMMIT;

