--   SELECT org, count(*) FILTER (WHERE term_date IS NULL) AS active
--   FROM v_people_coded GROUP BY org ORDER BY org;
-- And this should FAIL with "permission denied":
--   SELECT full_name FROM people LIMIT 1;
